CREATE TABLE emergency_calls (id BIGSERIAL PRIMARY KEY, call_ref TEXT NOT NULL UNIQUE, access_token TEXT NOT NULL, service TEXT NOT NULL, caller_name TEXT, caller_contact TEXT, location_text TEXT, status TEXT NOT NULL DEFAULT 'waiting', priority TEXT NOT NULL DEFAULT 'P1', operator_user_id TEXT, operator_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), answered_at TIMESTAMPTZ, closed_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now())